import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 15 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics and passages are distinct from
 * earlier Practice Tests. Every math answer key has been solved and checked.
 */

// ─────────────────────── PRACTICE TEST 15 · R&W M1 (27) ──────────────────────
const T15_RW_M1: SatQuestion[] = [
  { id: "t15rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The cartographer's hand was so ______ that her maps reproduced coastlines down to the smallest cove, omitting nothing a sailor might need.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["meticulous", "hasty", "indifferent", "reckless"], correct: 0, explanation: "Correct: A (meticulous). The clue is that her maps reproduce coastlines \"down to the smallest cove, omitting nothing\" — language describing extreme, careful attention to detail, which is exactly what \"meticulous\" means. B (hasty): hasty work is rushed and would miss small details, contradicting \"omitting nothing.\" C (indifferent): an indifferent mapmaker would not care about precision, the opposite of the described thoroughness. D (reckless): recklessness implies carelessness, clashing with maps so careful they include every cove." },
  { id: "t15rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee of trustees ______ scheduled to vote on the new endowment policy next week.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were"], correct: 0, explanation: "Correct: A (is). Subject-verb agreement rule: the verb agrees with the grammatical subject, not with a noun inside an intervening prepositional phrase. The subject is the singular collective noun \"committee\"; \"of trustees\" is a prepositional phrase that cannot govern the verb, so the singular \"is\" is required. B (are) and D (were) are plural and wrongly agree with \"trustees.\" C (have been) is also plural and additionally shifts to a perfect tense that the simple-present timeframe (\"next week\") does not call for." },
  { id: "t15rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Coral polyps house microscopic algae within their tissues; the algae photosynthesize and pass sugars to the coral, while the coral shelters the algae and supplies the compounds they need.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Coral and the algae inside them exchange resources to mutual benefit.", "Algae harm coral by stealing nutrients from it.", "Coral grow best when no algae are present.", "Algae cannot survive outside coral tissues."], correct: 0, explanation: "Correct: A. The text describes a reciprocal exchange — algae \"pass sugars to the coral\" while the coral \"shelters the algae and supplies the compounds they need\" — which is the definition of a mutually beneficial relationship. B contradicts the text: the algae help rather than \"harm\" the coral by stealing. C is unsupported and opposite the partnership the passage stresses. D makes a claim about algae surviving outside coral tissues that the passage never addresses." },
  { id: "t15rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The reservoir had dropped to a fraction of its normal level. ______, the town imposed strict limits on outdoor water use.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Consequently", "However", "By contrast"], correct: 1, explanation: "Correct: B (Consequently). The second sentence states an effect (water limits) that follows logically from the cause in the first (a depleted reservoir), so a cause-and-effect transition is needed. \"Consequently\" signals that result. A (Nevertheless), C (However), and D (By contrast) all signal contrast or concession, but there is no opposition here — the limits are the natural, expected response to the shortage, not a surprise that runs against it." },
  { id: "t15rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The kit contains everything a beginner needs ______ a brush, a palette, and a set of primary paints.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["needs, ", "needs: ", "needs; ", "needs "], correct: 1, explanation: "Correct: B (needs: ). Rule: a colon may introduce a list or explanation when it follows a grammatically complete independent clause. \"The kit contains everything a beginner needs\" is complete, and the colon properly introduces the list that specifies it. A (comma) is too weak to introduce a defining list of this kind. C (semicolon) is wrong because a semicolon must join two independent clauses, but \"a brush, a palette…\" is not a clause. D (no punctuation) leaves the boundary between clause and list unmarked, producing a run-on feel." },
  { id: "t15rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The novelist's later prose grew increasingly ______, stripping each sentence down to a handful of plain, unadorned words.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["spare", "ornate", "rambling", "verbose"], correct: 0, explanation: "Correct: A (spare). The clue \"stripping each sentence down to a handful of plain, unadorned words\" describes lean, minimal writing, which is what \"spare\" prose means. B (ornate) means heavily decorated — the opposite of \"plain, unadorned.\" C (rambling) means wandering and overlong, contradicting sentences stripped to a handful of words. D (verbose) means using too many words, again the reverse of the trimmed-down style described." },
  { id: "t15rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The fellowship is open only to applicants who have published at least one peer-reviewed article and who completed their degree within the past three years.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["An applicant who finished a degree five years ago is ineligible.", "Any published author qualifies regardless of degree date.", "Applicants with no publications can still apply.", "The fellowship is open to current students only."], correct: 0, explanation: "Correct: A. The text sets two requirements joined by \"and\": a peer-reviewed publication AND a degree completed \"within the past three years.\" A degree finished five years ago violates the second condition, so that applicant is ineligible — directly supported. B drops the degree-date requirement (\"regardless of degree date\"). C drops the publication requirement. D contradicts the text, which requires a completed degree, not enrollment, so current students would not qualify." },
  { id: "t15rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The lab confirmed the compound's structure using spectroscopy. ______, it verified the result with an independent crystallography test.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "In addition", "Otherwise", "Instead"], correct: 1, explanation: "Correct: B (In addition). The second sentence adds a second confirming method (crystallography) to the first (spectroscopy); both point the same direction, so an additive transition fits. A (However) signals contrast, but the two methods agree. C (Otherwise) introduces a consequence of not doing something, which does not fit. D (Instead) signals replacement, but crystallography supplements spectroscopy rather than replacing it." },
  { id: "t15rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Reviewers found the memoir refreshingly ______, since the author admitted her mistakes as readily as she recounted her successes.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["candid", "evasive", "boastful", "guarded"], correct: 0, explanation: "Correct: A (candid). The clue is that the author \"admitted her mistakes as readily as\" her successes — open, honest self-disclosure, which is what \"candid\" means. B (evasive) means dodging the truth, the opposite of admitting mistakes openly. D (guarded) likewise means withholding, contradicting the openness described. C (boastful) describes someone who plays up successes and hides faults, but the author owns her mistakes equally." },
  { id: "t15rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Arctic foxes change coat color with the seasons, growing white fur in winter to blend with snow and brown fur in summer to match the tundra.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Arctic foxes camouflage by switching coat color between seasons.", "Arctic foxes keep the same white coat all year.", "Arctic foxes are easily seen against the snow.", "Arctic foxes live only in summer climates."], correct: 0, explanation: "Correct: A. The whole text is about a fox \"changing coat color with the seasons\" to \"blend\" with snow in winter and \"match\" the tundra in summer — i.e., seasonal camouflage. B contradicts the change, claiming a single year-round coat. C contradicts the stated purpose of blending in (the white winter coat makes them hard to see against snow). D adds a false claim, since the text describes both winter and summer behavior." },
  { id: "t15rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither the manager nor the assistants ______ aware that the shipment had been rerouted overnight.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "Correct: B (were). Rule of proximity: in a \"neither…nor\" subject, the verb agrees with the nearer noun. The closer noun is the plural \"assistants,\" so the plural verb \"were\" is required. A (was), C (is), and D (has been) are all singular and would be correct only if the nearer noun were singular. They wrongly agree with \"manager\" rather than the adjacent \"assistants.\"" },
  { id: "t15rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The prototype overheated during its first trial. ______, the engineers gathered data that guided a far more reliable redesign.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 0, explanation: "Correct: A (Still). The first sentence reports a setback (overheating); the second reports a benefit drawn from it (useful data). That contrast — failure yet a positive result — calls for a concessive transition, and \"Still\" means \"even so / despite that.\" B (For instance) would introduce an example, but the second sentence is not an example of overheating. C (Therefore) signals a straightforward consequence, but gaining a better redesign from a failure is unexpected, not a simple result. D (In short) introduces a summary, which this is not." },
  { id: "t15rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A study reported recovery rates of 54% for the placebo group, 71% for the low-dose group, and 88% for the high-dose group.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Recovery rates rose as the dose increased.", "The placebo group recovered most often.", "The low-dose group had the highest recovery.", "All three groups recovered at the same rate."], correct: 0, explanation: "Correct: A. The figures increase in step with the dose: 54% (placebo) → 71% (low) → 88% (high), so recovery rises as dose increases. B is false: the placebo group's 54% is the lowest, not the highest. C is false: the low-dose 71% is the middle value, not the highest. D contradicts three clearly different percentages." },
  { id: "t15rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The archive holds a manuscript ______ scholars had assumed was lost in a fire decades ago.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "what", "where", "and it"], correct: 0, explanation: "Correct: A (that). A relative pronoun is needed to introduce a clause modifying the thing \"manuscript,\" and \"that\" correctly does so in this restrictive clause. B (what) cannot follow and modify a stated noun antecedent. C (where) introduces clauses about places, but a manuscript is an object, not a location. D (and it) would create a comma splice / run-on, joining two clauses with no proper relative link." },
  { id: "t15rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Stepping off the train, ______ the unfamiliar skyline left the traveler momentarily disoriented.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["stepping off the train, the unfamiliar skyline left the traveler disoriented", "the traveler, stepping off the train, felt disoriented by the unfamiliar skyline", "the unfamiliar skyline, stepping off the train, disoriented the traveler", "disoriented, the unfamiliar skyline confronted the traveler off the train"], correct: 1, explanation: "Correct: B. Modifier rule: an introductory participial phrase must be immediately followed by the noun it describes. \"Stepping off the train\" can only describe the traveler, and B places \"the traveler\" right after the phrase. A leaves \"the unfamiliar skyline\" as the thing stepping off the train — a dangling modifier. C likewise attaches the stepping to the skyline. D attaches \"disoriented\" to the skyline, again misassigning the modifier to a thing that cannot be disoriented or step off a train." },
  { id: "t15rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Researchers argue that spaced repetition — reviewing material at increasing intervals — fixes facts in memory more durably than cramming, because retrieval after a delay strengthens recall.", prompt: "Which finding, if true, would most strengthen the researchers' claim?", type: "mcq", choices: ["Students who reviewed at spaced intervals scored higher on a delayed test than students who crammed.", "Cramming takes less total study time than spaced review.", "Most students say they prefer cramming the night before.", "Both methods cover the same number of facts."], correct: 0, explanation: "Correct: A. The claim is specifically about durability — spaced repetition \"fixes facts more durably.\" A higher score on a delayed test for spaced reviewers is direct evidence of better long-term retention, so it strengthens the claim. B concerns study time, not durability. C concerns student preference, which is irrelevant to which method works better. D says the methods cover equal content, which says nothing about how long the facts are retained." },
  { id: "t15rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The conductor, together with the soloists, ______ rehearsing the symphony's demanding final movement.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "Correct: A (is). Rule: phrases beginning with \"together with,\" \"along with,\" or \"as well as\" are parenthetical and do not change the number of the subject. The subject is the singular \"conductor,\" so the singular \"is\" is required. B (are), C (were), and D (have been) are all plural and mistakenly treat \"soloists\" as part of the subject, when in fact it sits inside a set-off modifying phrase." },
  { id: "t15rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A researcher wants to stress that two independent labs reached the same surprising result. ______, both teams found the catalyst remained active even at near-freezing temperatures.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Remarkably", "However", "Otherwise"], correct: 1, explanation: "Correct: B (Remarkably). The setup says the writer wants to stress a \"surprising result\" shared by two independent labs, so an emphasis-on-the-striking transition fits, and \"Remarkably\" highlights the unexpected agreement. A (By contrast) and C (However) signal opposition, but the two labs agree rather than conflict. D (Otherwise) introduces an alternative outcome, which does not match a confirmed shared finding." },
  { id: "t15rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The play's ending is intentionally ______: audiences disagree sharply over whether the protagonist has triumphed or merely surrendered.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["ambiguous", "predictable", "tedious", "cheerful"], correct: 0, explanation: "Correct: A (ambiguous). The clue after the colon — audiences \"disagree sharply\" over what the ending means — defines an ending open to more than one interpretation, which is \"ambiguous.\" B (predictable) implies a single, expected outcome, the opposite of disagreement over meaning. C (tedious) describes something boring, a tone judgment the sentence does not make. D (cheerful) describes mood, not the interpretive openness the sentence stresses." },
  { id: "t15rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The rebate is offered only to customers who purchased a qualifying appliance after January 1 and who recycled their old model at a certified center.", prompt: "Which customer clearly qualifies for the rebate?", type: "mcq", choices: ["Someone who bought a qualifying appliance in March and recycled the old one at a certified center.", "Someone who bought a qualifying appliance last December.", "Someone who bought the appliance in March but kept the old model.", "Someone who never bought a qualifying appliance."], correct: 0, explanation: "Correct: A. Two conditions are joined by \"and\": a qualifying purchase after January 1 AND recycling the old model at a certified center. A March purchase plus certified recycling meets both, so this customer qualifies. B fails the date rule (December is before January 1). C fails the recycling rule (kept the old model). D fails the purchase requirement entirely." },
  { id: "t15rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the trail's washed-out section ______ they rebuilt the wooden footbridge over the creek.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["section, and then", "section and, then", "section then", "section, then"], correct: 0, explanation: "Correct: A (section, and then). \"The crew repaired…\" and \"they rebuilt…\" are two independent clauses; joining them requires a comma plus a coordinating conjunction (here \"and\"), with \"then\" as an adverb. B misplaces the comma after \"and,\" wrongly setting off \"then.\" C uses no punctuation or conjunction, creating a run-on. D uses only a comma before \"then,\" producing a comma splice, since \"then\" is not a coordinating conjunction." },
  { id: "t15rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Though celebrated for her ______ wit on stage, the comedian was notably soft-spoken and reflective in private interviews.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["sharp", "gentle", "timid", "muted"], correct: 0, explanation: "Correct: A (sharp). \"Though\" sets up a contrast between her on-stage wit and her private manner (\"soft-spoken and reflective\"). The blank must therefore be the opposite of soft-spoken — quick, biting wit, i.e., \"sharp.\" B (gentle), C (timid), and D (muted) all match her quiet private persona, so they would erase the contrast the word \"Though\" demands." },
  { id: "t15rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist observes that regions investing heavily in public transit saw lower commuting costs and slightly higher employment, crediting the link to expanded access to distant jobs.", prompt: "Which choice best describes the economist's explanation?", type: "mcq", choices: ["Better transit widened job access, lowering costs and lifting employment.", "Transit investment raised commuting costs for residents.", "Employment fell wherever transit expanded.", "Transit had no measurable effect on the regions."], correct: 0, explanation: "Correct: A. The economist credits \"expanded access to distant jobs\" as the mechanism linking transit investment to two outcomes: lower commuting costs and higher employment — exactly what A paraphrases. B reverses the cost effect (costs fell, not rose). C reverses the employment effect (employment rose, not fell). D denies any effect, contradicting the reported improvements." },
  { id: "t15rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The board delayed the merger ______ it still awaited a final review from outside auditors.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["merger because", "merger, because", "merger; because", "merger: because"], correct: 0, explanation: "Correct: A (merger because). When a subordinate \"because\" clause follows the main clause (rather than opening the sentence), no comma is needed before it. B inserts an unneeded comma before a trailing \"because\" clause. C uses a semicolon, which must join two independent clauses, but \"because it still awaited…\" is dependent. D uses a colon, which would wrongly frame the \"because\" clause as a set-off explanation or list." },
  { id: "t15rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The plant switched its boilers to natural gas. ______, it cut its sulfur emissions by more than seventy percent within a year.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "Correct: A (As a result). The emissions cut is a direct consequence of switching to cleaner-burning natural gas, so a cause-and-effect transition fits. B (Nevertheless) and D (On the other hand) signal contrast, but there is no opposition between the switch and the cleaner result. C (For example) would introduce an illustration, yet the second sentence is an outcome of the first, not an example of it." },
  { id: "t15rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The instructor's feedback was unfailingly ______, pointing to a specific line a student could revise rather than offering vague praise.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["concrete", "abstract", "evasive", "irrelevant"], correct: 0, explanation: "Correct: A (concrete). The clue contrasts pointing to \"a specific line\" with \"vague praise\"; specific, actionable feedback is \"concrete.\" B (abstract) means general and non-specific — the very thing the sentence says the feedback avoids. C (evasive) means dodging, also contradicting specificity. D (irrelevant) means unrelated, but the feedback is described as useful and on-point." },
  { id: "t15rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "After beavers were reintroduced to a drained marsh, their dams slowed the water's flow, raising the water table and allowing wetland plants and the insects that depend on them to return.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Reintroducing beavers set off a chain of changes that revived the wetland.", "Beavers directly planted the wetland vegetation.", "The water table fell after the beavers arrived.", "Wetland plants disappeared once the dams were built."], correct: 0, explanation: "Correct: A. The text traces a causal chain: beavers → dams slow flow → water table rises → plants and insects return. \"A chain of changes that revived the wetland\" captures this. B misstates the mechanism: beavers raised the water table that let plants return; they did not \"plant\" vegetation. C reverses the change — the water table rose, not fell. D contradicts the passage, which says plants returned, not disappeared." },
];

// ─────────────────────── PRACTICE TEST 15 · R&W M2 easy (27) ─────────────────
const T15_RW_M2E: SatQuestion[] = [
  { id: "t15rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The room felt very ______, so we opened a window to let in some fresh air.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["stuffy", "cold", "bright", "quiet"], correct: 0, explanation: "Correct: A (stuffy). Opening a window \"to let in some fresh air\" tells us the room's air was stale, which is what \"stuffy\" means. B (cold): opening a window would not warm a cold room, and the goal stated is fresh air, not heat. C (bright) describes light, not air quality. D (quiet) describes sound, giving no reason to want fresh air." },
  { id: "t15rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The three puppies ______ playing in the backyard.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Correct: B (are). The subject \"three puppies\" is plural, so it needs the plural present-tense verb \"are.\" A (is) and C (was) are singular and do not agree with a plural subject. D (am) is the first-person form used only with \"I.\"" },
  { id: "t15rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bees carry pollen from flower to flower as they collect nectar, helping the plants make seeds.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bees help plants reproduce by moving pollen between flowers.", "Bees damage flowers when they visit them.", "Bees never touch flowers.", "Bees only eat seeds."], correct: 0, explanation: "Correct: A. The text says bees carry pollen \"from flower to flower,\" \"helping the plants make seeds\" — making seeds is plant reproduction, so A restates the main point. B says \"damage,\" contradicting the helpful role. C says bees \"never touch flowers,\" but they carry pollen between flowers. D limits bees to eating seeds, which the text does not say (they collect nectar)." },
  { id: "t15rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The road ahead was flooded. ______, we took a different route home.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "Correct: B (So). The flooded road is the reason for taking another route, a cause-and-effect link, which \"So\" expresses. A (For example) would introduce an illustration, but the second sentence is a result, not an example. C (However) signals contrast, yet there is no opposition. D (Meanwhile) signals events happening at the same time, which is not the relationship here." },
  { id: "t15rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday she ______ a letter to her grandmother.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["write", "writes", "wrote", "writing"], correct: 2, explanation: "Correct: C (wrote). The time word \"Yesterday\" places the action in the past, so the past-tense \"wrote\" is required. A (write) and B (writes) are present tense and clash with \"yesterday.\" D (writing) is a participle that cannot serve as the sentence's main verb without a helping verb." },
  { id: "t15rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The puzzle was so ______ that we solved it in just a few minutes.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["easy", "hard", "expensive", "heavy"], correct: 0, explanation: "Correct: A (easy). Solving the puzzle \"in just a few minutes\" shows it was not difficult, i.e., \"easy.\" B (hard) is the opposite and would slow them down. C (expensive) describes cost, and D (heavy) describes weight — neither relates to how quickly a puzzle is solved." },
  { id: "t15rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Exercise strengthens muscles, improves mood, and helps people sleep better at night.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Exercise provides several health benefits.", "Exercise weakens the body.", "Exercise only affects sleep.", "Exercise should be avoided."], correct: 0, explanation: "Correct: A. The text lists three positive effects (stronger muscles, better mood, better sleep), which A sums up as \"several health benefits.\" B says \"weakens,\" contradicting \"strengthens.\" C says \"only\" sleep, ignoring the other two benefits. D advises avoiding exercise, the opposite of the text's positive tone." },
  { id: "t15rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He ate ______ apple before heading out the door.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "Correct: B (an). Rule: use \"an\" before a word that begins with a vowel sound; \"apple\" starts with a vowel sound, so \"an apple\" is correct. A (a) is used before consonant sounds. C (the only) and D (some) are grammatical but change the meaning, making the simple \"an\" the right fit for a single apple." },
  { id: "t15rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The hikers were ______ after climbing the steep trail all morning.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "rested", "cheerful", "hungry"], correct: 0, explanation: "Correct: A (tired). Climbing a steep trail \"all morning\" is exhausting, so the hikers would be \"tired.\" B (rested) is the opposite of what hard exercise produces. C (cheerful) and D (hungry) are not the direct result the clue points to — the sentence emphasizes physical exertion, which most logically yields tiredness." },
  { id: "t15rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My sister and I ______ excited about the trip next month.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Correct: B (are). The compound subject \"My sister and I\" is plural, so it takes the plural verb \"are.\" A (is) and C (was) are singular. D (am) is used only with the single subject \"I,\" not with a compound subject." },
  { id: "t15rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Owls hunt mainly at night, using sharp hearing and large eyes to find prey in near-total darkness.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Owls are adapted to hunt in the dark.", "Owls cannot see at all.", "Owls hunt only during the day.", "Owls do not eat prey."], correct: 0, explanation: "Correct: A. Sharp hearing and large eyes used \"to find prey in near-total darkness\" are adaptations for night hunting, which A states. B says owls \"cannot see at all,\" but the text credits their large eyes. C says they hunt by day, contradicting \"mainly at night.\" D says they do not eat prey, but the text says they hunt prey." },
  { id: "t15rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The power went out during the storm. ______, the whole neighborhood was dark.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "Correct: B (As a result). The darkness is the consequence of the power going out, a cause-and-effect link that \"As a result\" expresses. A (However) and D (Instead) signal contrast, but there is no opposition. C (For example) would introduce an illustration, yet the second sentence is the effect of the first, not an example of it." },
  { id: "t15rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night the choir ______ at the community center.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["sing", "sings", "sang", "singing"], correct: 2, explanation: "Correct: C (sang). \"Last night\" sets the action in the past, requiring the past-tense \"sang.\" A (sing) and B (sings) are present tense and clash with the past-time cue. D (singing) is a participle that cannot stand alone as the main verb without a helping verb." },
  { id: "t15rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The lemonade was very ______, so we added more sugar.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["sour", "sweet", "warm", "blue"], correct: 0, explanation: "Correct: A (sour). Adding sugar fixes a tart taste, so the lemonade was \"sour.\" B (sweet) is the opposite — already-sweet lemonade would not need more sugar. C (warm) describes temperature and D (blue) describes color, neither of which sugar would address." },
  { id: "t15rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The park is open from sunrise to sunset every day except major holidays.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The park is closed on major holidays.", "The park is open at midnight.", "The park is never open.", "The park is open only on holidays."], correct: 0, explanation: "Correct: A. \"Open… every day except major holidays\" means it is closed on those holidays, which A states. B is false: hours run \"sunrise to sunset,\" not at midnight. C contradicts \"open… every day.\" D reverses the exception — the park is open except on holidays, not only on them." },
  { id: "t15rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat licked ______ paws after the meal.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "Correct: A (its). \"Its\" is the singular possessive that matches the singular \"cat\" and shows the paws belong to it. B (it's) is a contraction of \"it is\" and cannot show possession. C (their) and D (they're) are plural forms that do not agree with the singular \"cat.\"" },
  { id: "t15rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Some birds travel huge distances each year. ______, the Arctic tern flies from pole to pole.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "Correct: A (For example). The second sentence gives a specific case (the Arctic tern) of the general claim that some birds travel huge distances, so an example transition fits. B (However) and C (Instead) signal contrast, but the tern supports the claim rather than opposing it. D (Otherwise) introduces an alternative condition, which does not match an illustration." },
  { id: "t15rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The backpack was too ______ to carry, so I removed some of the books.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "light", "small", "quiet"], correct: 0, explanation: "Correct: A (heavy). Removing books to make it easier to carry shows the backpack was \"heavy.\" B (light) is the opposite — a light backpack would not need lightening. C (small) and D (quiet) do not explain why one would take out books to make it carriable." },
  { id: "t15rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The keys ______ on the kitchen counter where I left them.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Correct: B (are). The subject \"keys\" is plural, so it requires the plural verb \"are.\" A (is) and C (was) are singular and do not agree. D (am) is used only with \"I.\"" },
  { id: "t15rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Maple trees produce a sweet sap that people boil down to make syrup.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Maple syrup is made from the sap of maple trees.", "Maple trees produce no sap.", "Maple syrup comes from the leaves.", "Maple sap cannot be cooked."], correct: 0, explanation: "Correct: A. The text says people \"boil down\" maple sap \"to make syrup,\" which A restates. B contradicts \"produce a sweet sap.\" C says the syrup comes from leaves, but the text says sap. D says the sap cannot be cooked, contradicting \"boil down.\"" },
  { id: "t15rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned to picnic outside. ______, rain forced us to eat indoors.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "Correct: A (However). The plan (picnic outside) and the outcome (eating indoors because of rain) oppose each other, so a contrast transition fits. B (Therefore) signals a result, but eating indoors is the reverse of the plan, not its natural consequence. C (For example) introduces an illustration, and D (Similarly) signals likeness — neither captures the contrast." },
  { id: "t15rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next year the school ______ to open a new science wing.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "Correct: B (plans). The singular subject \"school\" takes the singular present-tense \"plans,\" and present tense fits a current intention about \"next year.\" A (plan) is the plural form, which does not agree with the singular \"school.\" C (planned) is past tense, clashing with the future cue. D (planning) is a participle that cannot stand alone as the main verb." },
  { id: "t15rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The river was so ______ that we could see the pebbles on the bottom.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "muddy", "loud", "fast"], correct: 0, explanation: "Correct: A (clear). Being able to \"see the pebbles on the bottom\" means the water was transparent, i.e., \"clear.\" B (muddy) would hide the bottom, the opposite of the clue. C (loud) describes sound and D (fast) describes speed — neither relates to seeing through the water." },
  { id: "t15rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Wearing a seatbelt protects passengers, lowers the risk of injury, and is required by law in most places.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Seatbelts offer important protection and are widely required.", "Seatbelts increase the risk of injury.", "Seatbelts are never required.", "Seatbelts only protect drivers."], correct: 0, explanation: "Correct: A. The text lists protection, lower injury risk, and a legal requirement, which A combines as protection that is widely required. B says seatbelts \"increase\" injury risk, contradicting \"lowers the risk.\" C says they are \"never required,\" contradicting \"required by law in most places.\" D limits protection to drivers, but the text says \"passengers.\"" },
  { id: "t15rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She needed ______ eraser to fix her drawing.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "Correct: B (an). \"Eraser\" begins with a vowel sound, and the rule requires \"an\" before vowel sounds. A (a) precedes consonant sounds. C (the only) and D (some) are grammatical but alter the meaning, so the simple article \"an\" is the best fit for one eraser." },
  { id: "t15rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The trail was easy to follow. ______, signs marked every turn along the way.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In addition", "However", "Instead", "Otherwise"], correct: 0, explanation: "Correct: A (In addition). The second sentence adds another supporting reason (signs at every turn) to the first point that the trail was easy to follow, so an additive transition fits. B (However) and C (Instead) signal contrast, but both sentences agree. D (Otherwise) introduces an alternative condition, which does not match an added detail." },
  { id: "t15rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience was ______ as the magician revealed his final trick.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "sleepy", "angry"], correct: 0, explanation: "Correct: A (amazed). A magician's climactic \"final trick\" most naturally astonishes the crowd, so \"amazed\" fits. B (bored) and C (sleepy) are negative reactions that contradict a thrilling reveal. D (angry) is an unrelated negative emotion with no support in the sentence." },
];

// ─────────────────────── PRACTICE TEST 15 · R&W M2 hard (27) ─────────────────
const T15_RW_M2H: SatQuestion[] = [
  { id: "t15rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The diplomat's statement was carefully ______, affirming friendship in public while leaving every concrete commitment unspoken.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["noncommittal", "candid", "blunt", "forthright"], correct: 0, explanation: "Correct: A (noncommittal). The clue — affirming friendship \"while leaving every concrete commitment unspoken\" — describes a statement that avoids binding promises, which is what \"noncommittal\" means. B (candid), C (blunt), and D (forthright) all denote direct, open frankness, the opposite of a statement deliberately withholding any firm commitment." },
  { id: "t15rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The article opens by tracing the history of a single overlooked invention before broadening, in its later pages, into a claim about how minor tools reshape daily life.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It moves from a specific case to a broader general claim.", "It states a thesis and never develops it.", "It lists unrelated inventions at random.", "It repeats one definition throughout."], correct: 0, explanation: "Correct: A. The text says the article \"opens\" with one invention (specific) and then \"broadens\" into a claim about minor tools generally — a specific-to-general structure. B is false: the broadening claim is the development, so the thesis is developed. C is false: it focuses on a single invention, not a random list. D is false: there is no repeated definition; the piece moves from case to claim." },
  { id: "t15rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A sensor's accuracy held at 99% after 1,000 uses, 98% after 2,000 uses, and 90% after 5,000 uses.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Accuracy declined more sharply between 2,000 and 5,000 uses than before.", "Accuracy improved as uses increased.", "Accuracy stayed exactly constant.", "The sensor failed entirely by 2,000 uses."], correct: 0, explanation: "Correct: A. From 1,000 to 2,000 uses accuracy fell only 1 point (99% → 98%), but from 2,000 to 5,000 it fell 8 points (98% → 90%) — a much steeper decline, so A is supported. B reverses the trend (accuracy fell, not rose). C is false: the numbers change. D is false: at 2,000 uses the sensor was still 98% accurate, not failed." },
  { id: "t15rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The plan would shorten the harbor's shipping route considerably. ______, dredging the new channel would disturb a fragile oyster reef.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "Correct: B (However). The first sentence states a benefit (a shorter route); the second states a drawback (harm to a reef). That benefit-versus-cost opposition calls for a contrast transition. A (Therefore) and D (Accordingly) signal a consequence, but the drawback is not a result of the benefit. C (Likewise) signals similarity, but the two ideas pull in opposite directions." },
  { id: "t15rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship teaches participants to analyze data, to write reports, and ______ findings to clients.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "Correct: A (to present). Parallelism rule: items in a series must share the same grammatical form. The first two items are infinitives — \"to analyze\" and \"to write\" — so the third must also be an infinitive, \"to present.\" B (presenting) is a gerund, C (present) is a bare verb, and D (presented) is a past form; each breaks the parallel infinitive series." },
  { id: "t15rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The historian refuses to ______ the era, presenting its injustices as frankly as its achievements.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["romanticize", "condemn", "describe", "study"], correct: 0, explanation: "Correct: A (romanticize). Presenting injustices \"as frankly as\" achievements means the historian refuses to gloss over the era's faults — i.e., refuses to \"romanticize\" it. B (condemn) implies one-sided criticism, but she presents achievements too, not only flaws. C (describe) and D (study) are neutral acts she clearly does perform, so she would not \"refuse\" them." },
  { id: "t15rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the traditional account treats language as a fixed set of rules learned by imitation, the newer view frames it as a flexible system continually reshaped by its speakers.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast a traditional view of language with a newer, more flexible one.", "To prove that language never changes.", "To summarize only the traditional account.", "To argue that language cannot be studied."], correct: 0, explanation: "Correct: A. The \"Where the traditional… the newer view…\" framing sets two opposed views of language side by side — fixed-and-imitated versus flexible-and-reshaped — which is a contrast. B contradicts the \"flexible, continually reshaped\" view. C ignores the second view, which the text spends equal weight on. D makes a claim about studying language that the text never advances." },
  { id: "t15rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The expedition's success depended on three factors: favorable weather, reliable equipment, and ______ the team stayed in constant communication.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "whether", "if", "because"], correct: 0, explanation: "Correct: A (that). The list names three \"factors\"; the first two are noun phrases, so the third item must work as a noun-like element. \"That the team stayed in constant communication\" is a noun clause naming a factor, keeping the list parallel. B (whether) and C (if) introduce a condition or doubt, not a stated factor. D (because) introduces a reason, which does not fit a list of named factors." },
  { id: "t15rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the critic's review was studded with qualifications, each praise immediately tempered by a reservation.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unequivocal", "hesitant", "measured", "cautious"], correct: 0, explanation: "Correct: A (unequivocal). \"Far from being ___\" signals that the blank is the opposite of the review's actual character. The review is \"studded with qualifications,\" each praise \"tempered by a reservation\" — full of hedging — so it is far from \"unequivocal\" (one-sided, leaving no doubt). B (hesitant), C (measured), and D (cautious) all describe the qualified, reserved tone the review actually has, so they cannot be what it is \"far from.\"" },
  { id: "t15rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Although the manuscript bears no date, its references to a comet visible only in 1577 let scholars place its composition no earlier than that year.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The manuscript was written in 1577 or later.", "The manuscript was certainly written before 1577.", "The manuscript can be dated to the exact day.", "The manuscript mentions no astronomical events."], correct: 0, explanation: "Correct: A. A reference to a comet \"visible only in 1577\" means the manuscript could not have been written before that comet appeared, so its composition is \"no earlier than\" 1577 — that is, 1577 or later. B reverses this logic. C overstates the precision: the evidence gives a lower bound, not an exact day. D contradicts the very comet reference the passage relies on." },
  { id: "t15rw2h-11", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "A writer wants to concede a point before disputing it. The critics are right that the policy is costly. ______, its long-term savings far outweigh the initial expense.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nonetheless", "Therefore", "For instance", "In addition"], correct: 0, explanation: "Correct: A (Nonetheless). The setup says the writer first concedes a point (the policy is costly) and then disputes it. After the concession, a contrast transition is needed to pivot to the rebuttal about savings, and \"Nonetheless\" does exactly that. B (Therefore) and D (In addition) continue or build on an idea rather than turning against it. C (For instance) introduces an example, not a counterargument." },
  { id: "t15rw2h-12", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The professor's lectures were prized for their ______: she could compress a tangled debate into a single luminous sentence.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["lucidity", "obscurity", "verbosity", "monotony"], correct: 0, explanation: "Correct: A (lucidity). The clue after the colon — compressing \"a tangled debate into a single luminous sentence\" — describes remarkable clarity, which is \"lucidity.\" B (obscurity) means unclearness, the opposite. C (verbosity) means wordiness, contradicting compression into one sentence. D (monotony) means dullness, which \"luminous\" rules out." },
  { id: "t15rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A trial gave one group a daily walk and another no added activity; over six months, only the walking group showed measurable gains in cardiovascular fitness.", prompt: "Which conclusion is best supported by the text?", type: "mcq", choices: ["The daily walk likely contributed to the fitness gains.", "Both groups improved equally.", "Walking reduced cardiovascular fitness.", "Activity had no effect on either group."], correct: 0, explanation: "Correct: A. Only the group that added a daily walk showed fitness gains while the no-activity group did not, so the walk is the most likely cause of the difference. B is false: only one group improved. C reverses the result (the walking group gained, not lost, fitness). D denies the measured gain in the walking group." },
  { id: "t15rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The festival, ______ had drawn modest crowds for years, suddenly attracted tens of thousands after a viral video.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["which", "who", "where", "what"], correct: 0, explanation: "Correct: A (which). The commas signal a nonrestrictive relative clause describing the thing \"festival,\" and \"which\" is the relative pronoun for things in such clauses. B (who) refers to people, not a festival. C (where) refers to places and would need a location antecedent. D (what) cannot introduce a relative clause modifying a stated noun." },
  { id: "t15rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The negotiator's tone was deliberately ______, conceding nothing yet never giving offense, so talks could continue.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["diplomatic", "abrasive", "indifferent", "submissive"], correct: 0, explanation: "Correct: A (diplomatic). Conceding nothing \"yet never giving offense\" so talks can continue describes tactful, conflict-smoothing conduct — \"diplomatic.\" B (abrasive) means harsh and offensive, contradicting \"never giving offense.\" C (indifferent) means uncaring, but the negotiator works to keep talks going. D (submissive) means yielding, contradicting \"conceding nothing.\"" },
  { id: "t15rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Critics claimed the new bridge design was untested, but its engineer noted that three smaller spans built on the same principle had stood for over a decade without strain.", prompt: "How does the engineer respond to the critics?", type: "mcq", choices: ["By citing existing structures that prove the principle works.", "By admitting the design has never been used.", "By agreeing the design is unsafe.", "By avoiding any mention of past projects."], correct: 0, explanation: "Correct: A. The critics call the design \"untested,\" and the engineer counters by pointing to three existing spans built on the same principle that have stood a decade — evidence the principle works. B and C concede the critics' point, but the engineer rebuts it. D is false: the engineer's whole response is a reference to past projects." },
  { id: "t15rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The grant supports researchers ______ work bridges biology and computer science, a combination the foundation considers urgent.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["whose", "who's", "which", "that"], correct: 0, explanation: "Correct: A (whose). The blank must show that the \"work\" belongs to the \"researchers,\" which requires the possessive relative pronoun \"whose.\" B (who's) means \"who is\" and cannot show possession. C (which) and D (that) are relative pronouns but are not possessive, so they cannot link \"researchers\" to their \"work.\"" },
  { id: "t15rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The first study used a tiny sample and was easily dismissed. ______, the replication enrolled thousands of participants and produced the same striking result.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Similarly", "Therefore", "For example"], correct: 0, explanation: "Correct: A (By contrast). The first study (tiny, dismissed) is set against the replication (large, robust), an opposition that a contrast transition marks. B (Similarly) signals likeness, but the two studies differ sharply in scale and credibility. C (Therefore) signals a result, which does not fit. D (For example) introduces an instance, but the replication is a contrasting study, not an example of the first." },
  { id: "t15rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The essay's argument is ______, advancing through a chain of claims in which each step depends squarely on the one before it.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["rigorous", "haphazard", "circular", "trivial"], correct: 0, explanation: "Correct: A (rigorous). An argument advancing through carefully linked steps, each \"depending squarely on the one before,\" is disciplined and tightly reasoned — \"rigorous.\" B (haphazard) means disorganized, contradicting the orderly chain. C (circular) means reasoning that assumes its own conclusion, not a forward-building chain. D (trivial) means insignificant, which the careful structure does not suggest." },
  { id: "t15rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The poll found that support for the measure was 40% among first-time voters, 55% among occasional voters, and 68% among frequent voters.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Support rose as voting frequency increased.", "First-time voters supported the measure most.", "Occasional voters showed the least support.", "All groups supported it equally."], correct: 0, explanation: "Correct: A. Support climbs in step with voting frequency: 40% (first-time) → 55% (occasional) → 68% (frequent). B is false: first-time voters at 40% are lowest, not highest. C is false: occasional voters at 55% are the middle group, not the least. D contradicts three clearly different percentages." },
  { id: "t15rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having rehearsed the speech for weeks, ______ delivered it without once glancing at her notes.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the applause was immediate after she", "the candidate confidently", "the notes were unnecessary as she", "it was clear that the candidate"], correct: 1, explanation: "Correct: B. Modifier rule: the introductory phrase \"Having rehearsed the speech for weeks\" must be immediately followed by the person who did the rehearsing. Only B places that person — \"the candidate\" — right after the phrase, and she is the one who \"delivered it.\" A makes \"the applause\" the rehearser, C makes \"the notes\" the rehearser, and D makes \"it\" the rehearser; all three dangle the modifier." },
  { id: "t15rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The painter's late canvases grew ever more ______, dissolving recognizable shapes into pure fields of shifting color.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["abstract", "representational", "literal", "photographic"], correct: 0, explanation: "Correct: A (abstract). \"Dissolving recognizable shapes into pure fields of shifting color\" describes art moving away from depicting real objects — the definition of \"abstract.\" B (representational), C (literal), and D (photographic) all describe art that depicts recognizable subjects accurately, the opposite of dissolving shapes away." },
  { id: "t15rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Some scholars credited the city's growth to its harbor, but a recent study notes that inland rivals without harbors grew just as fast once a rail line reached them.", prompt: "How does the study complicate the scholars' explanation?", type: "mcq", choices: ["By showing that harborless cities grew equally fast with rail access.", "By confirming the harbor caused all the growth.", "By proving harbors slow city growth.", "By showing no cities grew at all."], correct: 0, explanation: "Correct: A. The scholars credit the harbor for growth, but the study shows inland cities \"without harbors grew just as fast\" once rail arrived — undercutting the harbor as the cause. B restates the very explanation the study challenges. C overstates the point (the study does not say harbors slow growth). D contradicts the study, which describes cities that did grow." },
  { id: "t15rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The report's conclusions, ______ surprised even its authors, have since been confirmed by two independent teams.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["which", "that", "who", "what"], correct: 0, explanation: "Correct: A (which). The commas mark a nonrestrictive clause describing \"conclusions,\" and \"which\" is the relative pronoun for things in nonrestrictive clauses. B (that) cannot introduce a nonrestrictive (comma-set-off) clause. C (who) refers to people, not conclusions. D (what) cannot modify a stated noun antecedent." },
  { id: "t15rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The treatment cleared the infection quickly in nearly every patient. ______, its high cost has kept it out of reach for many clinics.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Even so", "Consequently", "Likewise", "For example"], correct: 0, explanation: "Correct: A (Even so). The first sentence praises the treatment's effectiveness; the second notes a barrier (high cost) despite that effectiveness — a contrast that \"Even so\" (meaning \"despite that\") captures. B (Consequently) signals a result, but the cost barrier is not caused by the treatment working. C (Likewise) signals similarity, and D (For example) introduces an instance; neither fits the benefit-versus-barrier contrast." },
  { id: "t15rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The biographer treats her subject's contradictions not as flaws to be explained away but as ______ clues to a restless inner life.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["revealing", "trivial", "misleading", "irrelevant"], correct: 0, explanation: "Correct: A (revealing). The \"not… but…\" structure contrasts \"flaws to be explained away\" with valuable \"clues to a restless inner life\"; clues that expose something about the subject are \"revealing.\" B (trivial), C (misleading), and D (irrelevant) all diminish the contradictions' value, contradicting the biographer's view of them as meaningful clues." },
  { id: "t15rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A naturalist observed that a tide pool emptied of its top predator soon became overrun by mussels, which crowded out the algae and snails that had once thrived there.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Removing the top predator let mussels dominate and reduce the pool's diversity.", "The predator's removal increased the variety of life in the pool.", "Mussels declined once the predator was gone.", "Algae and snails took over the empty pool."], correct: 0, explanation: "Correct: A. With the top predator gone, mussels \"overran\" the pool and \"crowded out\" algae and snails, lowering the number of species — reduced diversity. B reverses the diversity effect (it dropped, not rose). C says mussels declined, but they took over. D says algae and snails took over, but they were the ones crowded out." },
];

