const T15_M_M1: SatQuestion[] = [
  { id: "t15m1-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x + 5 = 17, what is the value of x?", type: "mcq", choices: ["6", "11", "8", "5"], correct: 0, explanation: "Goal: solve for x. Start with 2x + 5 = 17. Subtract 5 from both sides: 2x + 5 − 5 = 17 − 5, so 2x = 12. Divide both sides by 2: x = 12/2 = 6. Check: 2(6) + 5 = 12 + 5 = 17. ✓ Answer: A (6). Trap: choice B (11) comes from subtracting only part or from 17 − 6; choice D (5) comes from ignoring the coefficient 2 and computing 17 − 5 − 5 or stopping early." },
  { id: "t15m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A recipe uses 3 cups of flour to make 12 cookies. How many cups of flour are needed for 36 cookies?", type: "mcq", choices: ["9", "12", "6", "15"], correct: 0, explanation: "Goal: scale the flour proportionally. Set up the proportion 3 cups / 12 cookies = x cups / 36 cookies. Cross-multiply: 12x = 3 × 36 = 108, so x = 108/12 = 9. Check: 9 cups makes 36 cookies, and 9/36 = 3/12. ✓ Answer: A (9). Trap: choice C (6) comes from adding 3 + 3 instead of scaling; the cookie count tripled (12 → 36), so the flour must triple too (3 → 9)." },
  { id: "t15m1-3", section: "math", domain: "Algebra", difficulty: "easy", prompt: "A line passes through the points (0, 2) and (4, 10). What is its slope?", type: "mcq", choices: ["2", "8", "3", "1/2"], correct: 0, explanation: "Goal: find slope = (change in y)/(change in x). Using (0, 2) and (4, 10): rise = 10 − 2 = 8, run = 4 − 0 = 4. Slope = 8/4 = 2. Check: starting at (0,2), going up 2 for every 1 right reaches (4, 2 + 4·2) = (4, 10). ✓ Answer: A (2). Trap: choice B (8) uses only the rise; choice D (1/2) inverts the fraction (run/rise instead of rise/run)." },
  { id: "t15m1-4", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = x² − 3x, what is the value of f(5)?", type: "mcq", choices: ["10", "25", "16", "−10"], correct: 0, explanation: "Goal: evaluate f at x = 5. Substitute: f(5) = (5)² − 3(5) = 25 − 15 = 10. Check: 5² = 25 and 3·5 = 15, and 25 − 15 = 10. ✓ Answer: A (10). Trap: choice B (25) drops the −3x term; choice D (−10) mishandles the sign, as if 15 − 25." },
  { id: "t15m1-5", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 30% of 80?", type: "mcq", choices: ["24", "26", "32", "16"], correct: 0, explanation: "Goal: compute 30% of 80. Convert the percent to a decimal: 30% = 0.30. Multiply: 0.30 × 80 = 24. Check: 10% of 80 is 8, so 30% is 3 × 8 = 24. ✓ Answer: A (24). Trap: choice B (26) and others come from subtracting (80 − 30 = 50) or misplacing the decimal; percent means 'per hundred,' so multiply by 0.30, not subtract 30." },
  { id: "t15m1-6", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has length 9 and width 4. What is its area?", type: "mcq", choices: ["36", "26", "13", "18"], correct: 0, explanation: "Goal: find the area of a rectangle = length × width. Compute: 9 × 4 = 36. Check: a 9-by-4 grid of unit squares holds 36 squares. ✓ Answer: A (36). Trap: choice B (26) is the perimeter, 2(9 + 4) = 26; choice C (13) is just the sum 9 + 4; choice D (18) is half the perimeter. Area requires multiplying the two sides." },
  { id: "t15m1-7", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x − 3 = 2x + 9, what is the value of x?", type: "mcq", choices: ["4", "3", "6", "2"], correct: 0, explanation: "Goal: solve for x with variables on both sides. Subtract 2x from both sides: 5x − 2x − 3 = 9, so 3x − 3 = 9. Add 3 to both sides: 3x = 12. Divide by 3: x = 4. Check: left = 5(4) − 3 = 17; right = 2(4) + 9 = 17. ✓ Answer: A (4). Trap: choice B (3) comes from dividing 9 by 3 without first adding the 3 back." },
  { id: "t15m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What are the solutions to x² − 5x + 6 = 0?", type: "mcq", choices: ["x = 2 and x = 3", "x = −2 and x = −3", "x = 1 and x = 6", "x = 5 and x = 6"], correct: 0, explanation: "Goal: solve the quadratic by factoring. Find two numbers that multiply to +6 and add to −5: those are −2 and −3. Factor: (x − 2)(x − 3) = 0. Set each factor to zero: x = 2 or x = 3. Check: 2² − 5(2) + 6 = 4 − 10 + 6 = 0 ✓ and 3² − 5(3) + 6 = 9 − 15 + 6 = 0 ✓. Answer: A. Trap: choice B uses negative roots, but (x − 2)(x − 3) requires positive solutions; choice C (1 and 6) multiplies to 6 but adds to 7, not 5." },
  { id: "t15m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of five numbers is 14. What is their sum?", type: "mcq", choices: ["70", "19", "14", "65"], correct: 0, explanation: "Goal: find the sum from the mean. Mean = sum ÷ count, so sum = mean × count = 14 × 5 = 70. Check: 70 ÷ 5 = 14, the given mean. ✓ Answer: A (70). Trap: choice B (19) adds 14 + 5; choice C (14) forgets to multiply by the count entirely." },
  { id: "t15m1-10", section: "math", domain: "Algebra", difficulty: "med", prompt: "A phone plan charges a $20 monthly fee plus $0.10 per text. Which expression gives the cost in dollars for t texts in a month?", type: "mcq", choices: ["20 + 0.10t", "0.10 + 20t", "20t + 0.10", "30t"], correct: 0, explanation: "Goal: model fixed plus variable cost. The fixed monthly fee is a constant $20 (it does not depend on t). The variable cost is $0.10 for each of t texts, written 0.10t. Total = 20 + 0.10t. Check with t = 10: 20 + 0.10(10) = 20 + 1 = $21, which matches $20 fee plus 10 texts at 10¢. ✓ Answer: A. Trap: choice B (0.10 + 20t) swaps the rate and the fee, charging $20 per text and a flat 10¢." },
  { id: "t15m1-11", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A right triangle has legs of length 6 and 8. What is the length of the hypotenuse?", type: "mcq", choices: ["10", "14", "48", "100"], correct: 0, explanation: "Goal: find the hypotenuse using the Pythagorean theorem, c² = a² + b². Compute: c² = 6² + 8² = 36 + 64 = 100, so c = √100 = 10. Check: 6² + 8² = 100 = 10². ✓ This is a 6-8-10 (scaled 3-4-5) triangle. Answer: A (10). Trap: choice B (14) adds the legs; choice D (100) forgets to take the square root of c²; choice C (48) is the area-related 6·8." },
  { id: "t15m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If 2^x = 32, what is the value of x?", type: "mcq", choices: ["5", "4", "6", "16"], correct: 0, explanation: "Goal: solve the exponential equation. Rewrite 32 as a power of 2: 2 → 4 → 8 → 16 → 32 is 2¹, 2², 2³, 2⁴, 2⁵, so 32 = 2⁵. Then 2^x = 2⁵ means x = 5. Check: 2⁵ = 32. ✓ Answer: A (5). Trap: choice D (16) divides 32 by 2, treating the relationship as linear; the exponent grows much more slowly than the value." },
  { id: "t15m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A store marks down a $50 shirt by 20%. What is the sale price?", type: "mcq", choices: ["$40", "$30", "$45", "$10"], correct: 0, explanation: "Goal: find the price after a 20% discount. Keeping 100% − 20% = 80% of the price: 0.80 × 50 = 40, so the sale price is $40. Check: 20% of 50 is 0.20 × 50 = $10 off, and 50 − 10 = $40. ✓ Answer: A ($40). Trap: choice B ($30) subtracts 20 dollars (treating the percent as dollars); choice D ($10) reports the discount amount, not the sale price." },
  { id: "t15m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 3(x − 2) = 15, what is the value of x?", type: "mcq", choices: ["7", "5", "3", "9"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 3: x − 2 = 15/3 = 5. Add 2 to both sides: x = 7. (Or distribute: 3x − 6 = 15, so 3x = 21, x = 7.) Check: 3(7 − 2) = 3(5) = 15. ✓ Answer: A (7). Trap: choice B (5) stops at x − 2 = 5 and forgets to add the 2 back." },
  { id: "t15m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has radius 5. What is its area, in terms of π?", type: "mcq", choices: ["25π", "10π", "5π", "100π"], correct: 0, explanation: "Goal: find the area of a circle = πr². With r = 5: area = π(5)² = 25π. Check: r² = 25, times π. ✓ Answer: A (25π). Trap: choice B (10π) uses the circumference formula 2πr = 2π(5) = 10π instead of the area formula; choice D (100π) uses diameter² instead of radius²." },
  { id: "t15m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + 6x + 9 = 25, and x > 0, what is the value of x?", type: "mcq", choices: ["2", "5", "−8", "16"], correct: 0, explanation: "Goal: solve for x with the constraint x > 0. Recognize the left side as a perfect square: x² + 6x + 9 = (x + 3)². So (x + 3)² = 25, and taking the square root of both sides gives x + 3 = ±5. Case +5: x = 5 − 3 = 2. Case −5: x = −5 − 3 = −8. Since x > 0, choose x = 2. Check: 2² + 6(2) + 9 = 4 + 12 + 9 = 25. ✓ Answer: A (2). Trap: choice B (5) takes √25 = 5 but forgets to solve x + 3 = 5; choice C (−8) is the rejected negative root." },
  { id: "t15m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A car travels 150 miles in 3 hours. At this rate, how far will it travel in 5 hours?", type: "grid", gridAnswers: ["250"], explanation: "Goal: find distance at a constant rate. First find the rate: 150 miles ÷ 3 hours = 50 miles per hour. Then multiply by the new time: 50 × 5 = 250 miles. Check: in 3 hours at 50 mph, 50 × 3 = 150 miles, matching the given. ✓ Answer: 250. Trap: simply scaling 150 by 5/3 also works (150 × 5/3 = 250); the error is adding distance for '2 more hours' without first finding the per-hour rate." },
  { id: "t15m1-18", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 4x + 2y = 20 and x = 3, what is the value of y?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve for y by substitution. Substitute x = 3 into 4x + 2y = 20: 4(3) + 2y = 20, so 12 + 2y = 20. Subtract 12 from both sides: 2y = 8. Divide by 2: y = 4. Check: 4(3) + 2(4) = 12 + 8 = 20. ✓ Answer: 4. Trap: dividing 20 by 2 before subtracting the 12 gives the wrong value; isolate the 2y term first." },
  { id: "t15m1-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(2x + 1) = 5, what is the value of x?", type: "grid", gridAnswers: ["12"], explanation: "Goal: solve a radical equation. Square both sides to remove the square root: (√(2x + 1))² = 5², so 2x + 1 = 25. Subtract 1: 2x = 24. Divide by 2: x = 12. Check: √(2·12 + 1) = √(24 + 1) = √25 = 5. ✓ Answer: 12. Trap: not fully squaring the 5 (using 5 instead of 25), or forgetting to subtract the 1 before dividing." },
  { id: "t15m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two angles of a triangle measure 50° and 65°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["65"], explanation: "Goal: find the third interior angle. The interior angles of any triangle sum to 180°. Subtract the two known angles: 180 − 50 − 65 = 180 − 115 = 65 degrees. Check: 50 + 65 + 65 = 180. ✓ Answer: 65. Trap: stopping at 50 + 65 = 115 (the sum of the two given angles) instead of subtracting from 180; also do not assume the triangle is equilateral." },
  { id: "t15m1-21", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A bag has 4 red, 5 green, and 3 blue marbles. If one marble is drawn at random, what is the probability it is green? Express your answer as a fraction.", type: "grid", gridAnswers: ["5/12", "0.4166", "0.417"], explanation: "Goal: find P(green) = favorable outcomes / total outcomes. Total marbles: 4 + 5 + 3 = 12. Favorable (green) outcomes: 5. So P(green) = 5/12 ≈ 0.417. Check: the three probabilities 4/12 + 5/12 + 3/12 = 12/12 = 1, as they should. ✓ Answer: 5/12. Trap: using a wrong denominator such as 5/7 (leaving out the 3 blue marbles) — the denominator must be the total of all 12 marbles." },
  { id: "t15m1-22", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = 2x + 1, what is the value of g(g(3))?", type: "mcq", choices: ["15", "7", "13", "9"], correct: 0, explanation: "Goal: evaluate a composed function from the inside out. First g(3) = 2(3) + 1 = 7. Then apply g to that result: g(7) = 2(7) + 1 = 15. Check: inner output 7, then 2·7 + 1 = 15. ✓ Answer: A (15). Trap: choice B (7) stops after the inner g(3) and never applies g a second time; doubling 3 twice without the +1 each time also misses." },
];

